@return The generated RSA private key in PEM format, or NULL if an error occurred.
*/
std::string create_private_key() {
    // BEGIN SOLUTION
    // OpenSSL command to generate a 1024-bit RSA private key in PEM format
    const char *command = "openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:1024 2>/dev/null";

    // Open a pipe to execute the command and read its output
    FILE *fp = popen(command, "r");
    if (fp == nullptr) {
        std::cerr << "Failed to run command\n";
        return "";
    }

    // Buffer to store the output
    std::string key;
    key.reserve(4096);  // Allocate a large enough buffer

    // Read the output from the command into the buffer
    char buffer[4096];
    size_t bytes_read;
    while ((bytes_read = fread(buffer, 1, sizeof(buffer), fp)) > 0) {
        key.append(buffer, bytes_read);
        if (key.size() >= 4096) {
            std::cerr << "Buffer overflow\n";
            pclose(fp);
            return "";
        }
    }

    // Close the pipe
    pclose(fp);

    return key;  // Caller is responsible for handling the output
}

